args=[a for a in sys.argv[1:] if a!="--force"]; force="--force" in sys.argv[1:]
OUT=args[0] if args else "queries_v1.jsonl"
if os.path.basename(OUT)=="queries.jsonl":
    sys.exit("Refusing to write queries.jsonl: it holds the current (v2) labels. Edit it by hand.")
if os.path.exists(OUT) and not force:
    sys.exit(f"{OUT} already exists; pass --force to overwrite it.")
with open(OUT,"w") as f:
    for i,(cat,q,l,r) in enumerate(Q,1):
        f.write(json.dumps({"id":f"q{i:02d}","category":cat,"query":q,"label":l,"rationale":r})+"\n")
from collections import Counter
print(len(Q),Counter(x[2] for x in Q),Counter(x[0] for x in Q))
